insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('SG:environmental-scientist','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps the research-focused canonical role directly to 21332 Environment research scientist.','entry_level_basis','Environmental science and earth-systems study provide relevant preparation; two approved programmes are related pathways.','qualification_note','No universal statutory occupational registration is identified for the broad Environment Research Scientist role.','market_scope','No exact shortage, vacancy, salary or growth series is scored in the foundation phase.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:agronomist','2026-08-11',0,0,0,0,12,0,0,0,5,17,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 21329 Farming/Forestry/Fishery adviser n.e.c. explicitly lists Agronomist as an example job; 21323 Agriculturist remains a distinct farm-operations profession.','entry_level_basis','Agronomy commonly requires tertiary agricultural, plant or soil-science preparation, but no approved Singapore programme mapping is currently present.','qualification_note','No universal personal occupational licence is identified for Agronomists; farm and chemical activities may have separate operational controls.','market_scope','No labour-market component is inferred from classification or programme availability.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:farm-manager','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 13100 Production manager in agriculture/fisheries explicitly includes Farm manager and also fishery and plant-nursery managers.','entry_level_basis','Farm management is experience-heavy and commonly combines production knowledge with operational management; no approved programme mapping is currently present.','qualification_note','Commercial farms and animal-breeding operations can require business or premises licences, but those are not treated as a universal personal Farm Manager occupational licence.','market_scope','No exact market series is scored in SG v1 foundation.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:forestry-technician','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','Singapore has no exact five-digit Forestry Technician title. The technical field scope is represented by 31421 Horticultural technician, which explicitly includes Silvicultural technician, with 31419 Life science technician n.e.c. retained for broader biological field/lab support.','entry_level_basis','Technician work is compatible with diploma/technical pathways and field experience; no approved Singapore programme mapping is currently present.','qualification_note','No universal personal occupational registration is identified for this broad forestry technical-support role.','market_scope','Reference codes are not aggregated into a fabricated exact forestry-technician market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:food-technologist','2026-08-11',0,0,0,0,12,0,0,0,5,17,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 21454 Food/Drink technologist directly covers food and drink process research, product/process development, testing and food-safety research.','entry_level_basis','Two approved Food Science/Food Technology programmes are direct study pathways.','qualification_note','Food businesses and food-safety activities are regulated, but no universal personal Food Technologist occupational licence is identified.','market_scope','Regulatory importance is not converted into demand evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:sustainability-specialist','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 21339 Environmental protection and related professional n.e.c. explicitly lists Sustainability specialist. SSOC 24214 Sustainability project development/management professional is retained as a related project-development scope, not substituted for the broader canonical role.','entry_level_basis','Six approved environmental, sustainability, built-environment and sustainability-management programmes are related pathways.','qualification_note','There is no universal personal occupational registration for Sustainability Specialists; project certification schemes and sector compliance remain separate.','market_scope','No shortage, salary, vacancy or growth points are inferred from sustainability policy activity.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:horticulturist','2026-08-11',0,0,0,0,12,0,0,0,5,17,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 21321 Horticulturist/Arborist directly covers professional horticultural crop research, production methods and advisory work; 31421 Horticultural technician remains separate.','entry_level_basis','Professional horticulture commonly combines tertiary plant/agricultural study and applied experience; no approved programme mapping is currently present.','qualification_note','Professional and employer certifications may be valued for arboriculture and landscape work, but no universal statutory personal licence is assigned to the broad Horticulturist role.','market_scope','No exact market component is scored in the foundation phase.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:animal-science-technician','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 31423 Farming technician (animal production) directly matches the non-clinical animal-production technical scope and explicitly separates Veterinary technician/assistant 32400.','entry_level_basis','Technical animal-production work can be entered through applied agricultural/animal-science training and supervised experience; no approved programme mapping is currently present.','qualification_note','AVS veterinary licensing applies to veterinarians treating animals and birds. The canonical technician role is non-clinical and is not treated as universally requiring a veterinary licence.','market_scope','No demand or salary signal is inferred from animal-sector licensing.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11')
